// Computer Setup: installs the ClipBridge agent on the computer your dongle is
// plugged into, and checks it's running. The computer type is kept on the phone.

const RAW = 'https://raw.githubusercontent.com/HaydenKaufmann/clipbridge-agent/main/';
const INSTALL = {
  macOS: 'curl -fsSL ' + RAW + 'install.sh | sh',
  Linux: 'curl -fsSL ' + RAW + 'install.sh | sh',
  Windows: 'irm ' + RAW + 'install.ps1 | iex',
};
const UNINSTALL = {
  macOS: '~/.local/bin/clipbridge-agent uninstall',
  Linux: '~/.local/bin/clipbridge-agent uninstall',
  Windows: '& "$env:LOCALAPPDATA\\ClipBridge\\clipbridge-agent.exe" uninstall',
};
const NAMES = { macos: 'macOS', windows: 'Windows', linux: 'Linux' };

// The computer's OS: what the agent said last, what the user chose, or ask.
async function computer() {
  let os = await cb.storage.get('os');
  if (!os) {
    os = await cb.choose('What does your computer run?', ['macOS', 'Windows', 'Linux']);
    if (os) await cb.storage.set('os', os);
  }
  return os;
}

async function changeComputer() {
  await cb.storage.remove('os');
  const os = await computer();
  return os ? 'Computer: ' + os : null;
}

// Opens a terminal the installer can run in: Terminal, PowerShell, or the
// desktop's terminal on Linux.
async function openTerminal(os) {
  if (os === 'macOS') {
    await cb.keys('cmd+space');
    await cb.wait(600);
    await cb.type('Terminal');
    await cb.wait(400);
    await cb.keys('return');
  } else if (os === 'Windows') {
    await cb.keys('win+r');
    await cb.wait(600);
    await cb.type('powershell');
    await cb.keys('return');
  } else {
    await cb.keys('ctrl+alt+t');
  }
  await cb.wait(2000);
}

async function runInTerminal(os, line, what) {
  const ok = await cb.confirm(
    'This opens a terminal on your ' + os + ' computer and types:\n\n' + line +
      '\n\n' + what + ' Have the computer unlocked and in front of you.',
  );
  if (!ok) return false;
  await openTerminal(os);
  await cb.type(line);
  await cb.keys('return');
  return true;
}

async function installAgent() {
  const status = await cb.agent.status();
  if (!status.connected) return 'Connect to your dongle first.';
  const os = await computer();
  if (!os) return null;
  const typed = await runInTerminal(
    os,
    INSTALL[os],
    'It downloads the ClipBridge agent from GitHub, checks it, and sets it to start at login.',
  );
  if (!typed) return null;
  cb.notify('Installing… watch the terminal.');
  // The dongle switches to agent mode a couple of seconds after it starts.
  for (let i = 0; i < 15; i++) {
    await cb.wait(2000);
    if ((await cb.agent.status()).agent) return 'The agent is installed and running.';
  }
  return 'The agent isn\'t running yet. Check the terminal for a message.';
}

async function uninstallAgent() {
  const os = await computer();
  if (!os) return null;
  const typed = await runInTerminal(
    os,
    UNINSTALL[os],
    'It stops the agent and stops it starting at login.',
  );
  return typed ? 'Uninstalling… the dongle goes back to typing in a few seconds.' : null;
}

async function testAgent() {
  const status = await cb.agent.status();
  if (!status.connected) return 'Connect to your dongle first.';
  try {
    const p = await cb.agent.ping();
    if (p.os && NAMES[p.os]) await cb.storage.set('os', NAMES[p.os]);
    return 'The agent answered in ' + p.ms + ' ms' +
      (p.version ? ': version ' + p.version : '') +
      (p.os ? ' on ' + (NAMES[p.os] || p.os) : '') + '.';
  } catch (e) {
    return e.message;
  }
}
